M = 10 ** 9 + 7
dp = {}

def MODmul(a, b):
	return a % M * (b % M) % M

def MODdiv(a, b):
	return a * pow(b, M - 2, M) % M

def MODdivFake(a, b):
	return (a, b)

def MODadd(a, b):
	return (a % M + b % M) % M

def MODsub(a, b):
	return (a % M - b % M + M) % M

def gcd(a, b):
	if (a, b) in dp:
		return dp[a, b]
	if a == 0:
		dp[a, b] = b
		return b
	dp[a, b] = gcd(b % a, a)
	return dp[a, b]

def gm(c, r, k):
	if c % 2:
		m = (c - 1) // 2
		rm_1 = pow(r - 1, m, M)
		rm = pow(r, m, M)
		n1 = MODmul(rm, r + k)
		n2 = rm_1 * (1 - r - k)
		d = MODmul(rm, r + k)
		return [MODadd(n1, n2), d]
	m = c // 2
	rm = pow(r, m, M)
	return [MODsub(rm, pow(r - 1, m, M)), rm]

def fracAdd(n1, d1, n2, d2):
	d1 = d1
	d2 = d2
	g = gcd(d1, d2)
	lcm = d1 * (d2 / g)
	n1 = n1 * (lcm // d1) % M
	n2 = n2 * (lcm // d2) % M
	n = (n1 + n2) % M
	return [int(n), int(lcm)]

def getFrac(n, k, c):
	if n == 1:
		return [1, 1]
	if c == 1:
		return [1, n]
	if n <= k:
		if c == 2:
			return [2 * n + k - 1, n * (n + k)]
		else:
			r = (n + k) % k
			if r == 0:
				r = n
			(n1, d1) = (1, n)
			(n2, d2) = (n - 1, n)
			(n3, d3) = gm(c - 1, r, k)
			n2 = MODmul(n2, n3)
			d2 = MODmul(d2, d3)
			return fracAdd(n1, d1, n2, d2)
	r = n % k
	if r == 1:
		return [1, 1]
	if r == 0:
		r = k
	return gm(c, r, k)

def ans(n, k, c):
	(n, d) = getFrac(n, k, c)
	g = gcd(n, d)
	(n, d) = [n // g, d // g]
	return MODdiv(n, d)
for _ in range(int(input())):
	(n, k, c) = map(int, input().split())
	print(ans(n, k, c))
